Now engine.js. Let me write carefully.

```js
import { CARDS, DECKS, makeDeck, shuffle } from './cards.js';

export class DuelError extends Error {}

const other = s => s === 'you' ? 'opp' : 'you';
const MAX_LP = 99999;

export class Duel {
  constructor({ playerName, oppName, deckId, oppDeckId, lp = 8000, mode='solo', first }) {
