  }
}
```

Fields:
- names
- deck, extra, hand, gy, banished
- field
- emz
- lp
- turn
- turnNo
- flags
- winner
- logs
- mode
- deckIds

Constructor draw 5 each, no events. Determine first: opts.first || (Math.random()<.5?'you':'opp'). Player might be second; then UI triggers AI turn on start. Starting hand 5.

Log entries: `{ text, tone, turn, t }`. Add initial logs:
- `デュエル開始 — 24ゾーン / LP0勝利`
- `先攻: ${name}`.
- draw logs? maybe not each draw to avoid noise; add "5枚をドロー".

Methods validation:
```js
requireTurn(side){ if (this.winner) throw; if (this.turn!==side) throw new DuelError('あなたのターンではありません'); }
```

`handCard(side, uid)`.

Zones helper:
```js
monsterZones(side) { return this.field[side].monster; }
ownMonsters(side) {
  const list=[];
  this.field[side].monster.forEach((e,i)=>{ if(e) list.push({kind:'monster', idx:i, entry:e}); });
  this.emz.forEach((e,i)=>{ if(e && e.owner===side) list.push({kind:'emz', idx:i, entry:e}); });
  return list;
}
enemyMonsters(side) => ownMonsters(other(side))
```

`entryAt(side, kind, idx)` returns entry.

`removeEntry(side, kind, idx)`.

`toGY(side, entry, ev, reason)`:
```js
const card = entry.card;
this.gy[side].push(card);
ev.push({ type:'toGY', side, card, reason });
```

Destroy:
```js
destroyEntry(side, kind, idx, ev, reason='effect') {
  const e = this.entryAt(side,kind,idx);
  if (!e) return null;
  if (kind==='monster') this.field[side].monster[idx]=null;
  else if (kind==='emz') this.emz[idx]=null;
  else if (kind==='spell') this.field[side].spell[idx]=null;
  else if (kind==='field') this.field[side].field=null;
  this.gy[side].push(e.card);
  ev.push({ type:'destroy', side, kind, idx, card:e.card, uid:e.card.uid, reason });
  return e;
}
```
Tribute uses same but event type 'tribute' maybe. Use destroy with reason 'tribute'; UI animation might show shatter. Fine. Log text "生贄に捧げた".

`sendSpellToGY(side, entry, ev)`: gy push + event 'toGY'.

`atkOf(side, entry)`: base + atkMod + field bonus.
`defOf`.
`effectiveStats(side, entry)`.

Set monster DEF doesn't get field atk; def bonus.

Normal summon:
```js
normalSummon(side, uid, zoneIdx, mode='atk', ev=[]) {
  this.requireTurn(side);
  if (this.flags.summoned) throw new DuelError('このターンは既に通常召喚しています');
  const handIdx = this.hand[side].findIndex(c=>c.uid===uid);
  if (handIdx<0) throw new DuelError('そのカードは手札にありません');
  const card = this.hand[side][handIdx];
  if (card.kind !== 'monster' || card.extra) throw new DuelError('通常召喚できるモンスターではありません');
  if (zoneIdx<0||zoneIdx>4||this.field[side].monster[zoneIdx]) throw new DuelError('モンスターゾーンが埋まっています');
  const need = this.tributesNeeded(card.level);
  const own = this.ownMonsters(side);
  if (own.length < need) throw new DuelError(`生贄が${need}体必要です`);
