```js
function onZoneClick(side, kind, idx) {
  if (!duel || app.busy || duel.winner) return;
  const entry = kind==='emz' ? duel.emz[idx] : duel.entryAt(side,kind,idx);
  // target attack
  if (sel?.type==='field' && sel.attackReady && kind!=='direct') {
    if (kind==='emz') {
      if (entry && entry.owner==='opp') performAttack(sel, {kind:'emz', idx});
      return;
    }
    if (side==='opp' && entry && (kind==='monster')) { performAttack(sel, {kind:'monster', idx}); return; }
    // clicking own board cancels? no
  }
  // drop
  if (side==='you' && canDropOn(side,kind,idx) && sel) { executeDrop(kind, idx); return; }
  if (kind==='emz') {
    if (!entry) { deselect(); return; }
    if (entry.owner==='you') { selectField('you','emz',idx); }
    else { openCardDetail(entry.card, entry); }
    return;
  }
  if (side==='you' && entry) { selectField('you',kind,idx); return; }
  if (side==='opp' && entry) { openCardDetail(entry.card, entry); return; }
  deselect();
}
```
