/* Lobby, player profile, online room list, room detail. */

import { DECKS, DECK_LIST, deckSize } from './cards.js';
import {
  profile, online, subscribe, renamePlayer, setDeck, addResult, getRoom,
  joinRoom, acceptChallenger, avatarColor, initials, leaveOtherRoom,
} from './rooms.js';
import {
  $, app, esc, toast, showScreen, openModal, closeModal, sleep,
} from './ui-core.js';
import { startDuel } from './ui-duel.js';
import { sfx } from './fx.js';

const CPU_NAMES = ['CPU / アストラ', 'CPU / ノクターン', 'CPU / ヴェルム', 'CPU / セラ', 'CPU / ゼロ', 'CPU / オルガ'];
const CPU_DECKS = ['flame', 'abyss', 'gear'];

export function initLobby() {
  app.onExitDuel = showLobby;

  $('soloBtn').addEventListener('click', () => startSolo());
  $('myRoomBtn').addEventListener('click', () => openRoomDetail('mine'));
  $('enterRoomBtn').addEventListener('click', () => openRoomDetail('mine'));
  $('roomBackBtn').addEventListener('click', () => showLobby());

  $('nameBtn').addEventListener('click', openNameModal);

  $('deckOptions').addEventListener('click', e => {
    const btn = e.target.closest('[data-deck]');
    if (!btn) return;
    setDeck(btn.dataset.deck);
    renderDeckPicker();
    renderMyRoom();
    sfx('select');
    toast(`${DECKS[btn.dataset.deck].name} に変更しました`, 'good');
  });

  $('roomList').addEventListener('click', e => {
    const join = e.target.closest('[data-join]');
    if (join) { e.stopPropagation(); onJoinRoom(join.dataset.join); return; }
    const row = e.target.closest('[data-open-room]');
    if (row) openRoomDetail(row.dataset.openRoom);
  });

  renderLobbyAll();
  showScreen('lobby');
  subscribe(onRoomsUpdate);
}

export function showLobby() {
  showScreen('lobby');
  renderLobbyAll();
}

function onRoomsUpdate() {
  renderOnline();
  if (app.screen === 'lobby') {
    renderProfile();
    renderMyRoom();
    renderRecord();
    renderRooms();
  } else if (app.screen === 'room') {
    renderOnline();
  }
}

/* ---------------- profile ---------------- */
function openNameModal() {
  const body = openModal(`
    <div class="modal-title">プレイヤー名</div>
    <p class="modal-sub">ルームリストとデュエル画面に表示されます。</p>
    <input class="text-input" id="nameInput" maxlength="18" value="${esc(profile.name)}" autocomplete="off" spellcheck="false">
    <div class="modal-actions">
      <button class="primary-btn" id="saveNameBtn">保存する</button>
      <button class="secondary-btn" data-close-modal>キャンセル</button>
    </div>
  `);
  const input = body.querySelector('#nameInput');
  input.focus();
  input.select();
  const save = () => {
    if (renamePlayer(input.value)) {
      renderProfile();
      renderMyRoom();
      closeModal();
      toast('プレイヤー名を変更しました', 'good');
      sfx('select');
    } else {
      toast('名前を入力してください', 'bad');
    }
  };
  body.querySelector('#saveNameBtn').addEventListener('click', save);
  input.addEventListener('keydown', e => { if (e.key === 'Enter') save(); });
}

function renderProfile() {
  $('myName').textContent = profile.name;
  const av = $('myAvatar');
  av.textContent = initials(profile.name);
  av.style.background = `linear-gradient(140deg, ${avatarColor(profile.name)}, #6c8dff)`;
  renderRecord();
}

function renderRecord() {
  const total = profile.wins + profile.losses;
  const rate = total ? Math.round((profile.wins / total) * 100) : 0;
  $('recordBody').innerHTML = `
    <div class="record-item win"><b>${profile.wins}</b><span>WINS</span></div>
    <div class="record-item loss"><b>${profile.losses}</b><span>LOSSES</span></div>
    <div class="record-item rate"><b>${total ? rate + '%' : '—'}</b><span>WIN RATE</span></div>
  `;
  $('recordSub').textContent = total ? `${total} DUELS` : 'SOLO + ONLINE';
}

/* ---------------- decks ---------------- */
function renderDeckPicker() {
  const current = DECKS[profile.deckId] || DECKS.flame;
  $('deckOptions').innerHTML = DECK_LIST.map(d => `
    <button class="deck-option ${d.id === profile.deckId ? 'selected' : ''}" data-deck="${d.id}" style="--accent:${d.accent}">
      <b>${d.name}</b>
      <span><i>●</i> ${deckSize(d)}枚 + EX ${d.extra.length}</span>
    </button>
  `).join('');
  $('deckCount').textContent = `${deckSize(current)}枚 + EX ${current.extra.length}`;
  $('deckDesc').textContent = current.desc;
}

/* ---------------- my room ---------------- */
function renderMyRoom() {
  const my = online.myRoom;
  if (!my) return;
  $('myRoomCode').textContent = my.code;
  const created = new Date(profile.room.createdAt);
  const time = created.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  $('myRoomSub').textContent = `${time} に自動作成 · あなたがホスト`;

  const challenger = my.challenger;
  $('myRoomBody').innerHTML = `
    <div class="room-occupant">
      <span class="avatar" style="background:linear-gradient(140deg, ${avatarColor(profile.name)}, #6c8dff)">${initials(profile.name)}</span>
      <div class="who"><b>${esc(profile.name)}</b><span>HOST / あなた</span></div>
      <span class="ready-chip">参加中</span>
    </div>
    ${challenger ? `
      <div class="room-occupant">
        <span class="avatar" style="background:${challenger.color}">${initials(challenger.name)}</span>
        <div class="who"><b>${esc(challenger.name)}</b><span>CHALLENGER · ${challenger.rank}</span></div>
        <span class="ready-chip">準備OK</span>
      </div>` : `
      <div class="room-occupant" style="border-style:dashed; opacity:.75">
        <span class="avatar" style="background:#20283f; color:#7f8db0">?</span>
        <div class="who"><b>挑戦者を待っています</b><span>SLOT 2 / OPEN</span></div>
        <span class="ready-chip" style="color:#ffcf9d;border-color:rgba(255,207,107,.25);background:rgba(255,207,107,.06)">募集中</span>
      </div>`}
    <div class="my-room-row"><span>ルール</span><b>LP 8000 · 24 ZONES · LP0勝利</b></div>
    <div class="my-room-row"><span>デッキ</span><b>${esc((DECKS[profile.deckId] || DECKS.flame).name)}</b></div>
  `;
  $('autoJoinNote').textContent = '起動と同時に自動作成・自動参加。退出しても次回起動時に再作成されます。';
}

/* ---------------- online room list ---------------- */
function renderOnline() {
  const el = $('onlineCount');
  if (el) el.textContent = online.count;
  const rc = $('roomOnlineCount');
  if (rc) rc.textContent = online.count;
}

function renderRooms() {
  const list = $('roomList');
  if (!list) return;
  $('roomCount').textContent = online.rooms.length;
  const fresh = [];
  list.innerHTML = online.rooms.map(room => {
    const isNew = !app.seenRooms.has(room.id);
    if (isNew) fresh.push(room.id);
    return roomRowHTML(room, isNew);
  }).join('');
  for (const id of fresh) app.seenRooms.add(id);
}

function roomRowHTML(room, fresh) {
  const status = room.mine
    ? { label: '参加中', cls: 'open' }
    : room.status === 'open' ? { label: '募集中', cls: 'open' }
      : room.status === 'full' ? { label: '満室', cls: 'full' }
        : { label: '対戦中', cls: 'dueling' };
  const joinLabel = room.mine ? '入室中' : room.status === 'open' ? '参加' : room.status === 'full' ? '満室' : '対戦中';
  const disabled = !room.mine && room.status !== 'open';
  const host = room.host;

  return `<div class="room-row ${room.mine ? 'mine' : ''} ${fresh ? 'fresh' : ''}" data-open-room="${room.id}" title="${esc(room.note || '')}">
    <div class="room-host">
      <span class="host-avatar" style="background:${host.color}">${initials(host.name)}</span>
      <div class="room-host-text">
        <b>${esc(host.name)} ${room.mine ? '<span class="crown">♛</span>' : ''}</b>
        <span>${room.code} · ${room.mine ? 'あなたのルーム' : host.rank} · ${host.ping}ms</span>
      </div>
    </div>
    <div class="room-mode-chip">${room.mode}</div>
    <div class="room-cell mono">${room.lp}</div>
    <div class="room-cell mono">${room.zones}Z</div>
    <div class="room-cell mono">${room.players}/${room.max}</div>
    <div><span class="room-status ${status.cls}"><i></i>${status.label}</span></div>
    <button class="room-join ${room.mine ? 'mine' : ''}" data-join="${room.id}" ${disabled ? 'disabled' : ''}>${joinLabel}</button>
  </div>`;
}

function onJoinRoom(id) {
  if (id === online.myRoom?.id) { openRoomDetail('mine'); return; }
  const room = getRoom(id);
  if (!room) { toast('ルームが見つかりません', 'bad'); return; }
  if (room.status !== 'open' || room.players >= 2) {
    toast('このルームは満室です', 'bad');
    return;
  }
  const joined = joinRoom(id);
  if (!joined) { toast('参加できませんでした', 'bad'); return; }
  toast(`${room.host.name} のルームに参加しました`, 'good');
  sfx('select');
  openRoomDetail(joined);
}

/* ---------------- room detail ---------------- */
export function openRoomDetail(id) {
  let room = id === 'mine' ? online.myRoom : getRoom(id);
  if (!room && online.joinedOther && (id === online.joinedOther.id || id === 'joined')) room = online.joinedOther;
  if (!room) { toast('ルームが見つかりません', 'bad'); return; }
  app.roomId = room.id;
  app.roomRef = room;
  renderRoomDetail(room);
  showScreen('room');
}

function renderRoomDetail(room) {
  if (room.mine) room = online.myRoom;
  app.roomRef = room;
  $('roomHeadCode').textContent = room.code;

  const isMine = !!room.mine;
  const host = isMine
    ? { name: profile.name, rank: 'HOST', tag: 'あなた', color: avatarColor(profile.name) }
    : room.host;
  const guest = isMine
    ? room.challenger
    : { name: profile.name, rank: 'CHALLENGER', tag: 'あなた', color: avatarColor(profile.name) };
  const startLabel = isMine
    ? (guest ? `${esc(guest.name)} とデュエル` : '挑戦者を募集してデュエル')
    : `${esc(host.name)} とデュエル`;

  const deckOpts = DECK_LIST.map(d => `
    <button class="room-deck-opt ${d.id === profile.deckId ? 'selected' : ''}" data-deck="${d.id}" style="--accent:${d.accent}">
      <span class="dot"></span>
      <b>${d.name}</b>
      <span>${deckSize(d)}枚</span>
    </button>
  `).join('');

  $('roomDetailBody').innerHTML = `
    <section class="room-hero">
      <div>
        <p class="eyebrow"><span class="eyebrow-dot"></span>${isMine ? 'YOUR ROOM / AUTO JOINED' : room.mode + ' ROOM / JOINED'}</p>
        <h1>${isMine ? 'あなたのルームで' : 'このルームで'}<br><span>LPを0にしろ。</span></h1>
        <p>${isMine
          ? '起動時に自動で作成されたあなたのルームです。挑戦者を迎えて、24ゾーンのデュエルを開始します。'
          : `${esc(host.name)} のルームに参加しています。24ゾーン・カード画像なし・相手LPを0にすれば勝利。`}</p>
      </div>
      <div class="room-hero-side">
        <div class="room-code-big">${room.code}</div>
        <div class="room-code-actions">
          <button class="chip-btn" id="copyRoomBtn">コードをコピー</button>
          <button class="chip-btn" id="roomOnlineChip"><i class="pulse-dot"></i> ${online.count} online</button>
        </div>
        <span class="tiny">${isMine ? '自動参加中 · 退出不可（常時参加）' : '参加済み · 準備完了'}</span>
      </div>
    </section>

    <div class="room-grid">
      <section class="panel room-info-panel">
        <div class="panel-head"><h2>ルール</h2><span class="muted">FIXED</span></div>
        <div class="room-rules">
          <div class="rule-tile"><span>LIFE POINT</span><b><em>${room.lp}</em> スタート</b></div>
          <div class="rule-tile"><span>FIELD</span><b><em>24</em> ゾーン</b></div>
          <div class="rule-tile"><span>WIN CONDITION</span><b>相手LPを<em>0</em>に</b></div>
          <div class="rule-tile"><span>CARD IMAGE</span><b><em>0</em> 枚 / テキスト</b></div>
        </div>
        <div class="panel-head" style="margin-top:6px"><h2>プレイヤー</h2><span class="muted">2 SLOTS</span></div>
        <div class="room-players">
          <div class="player-slot">
            <span class="avatar" style="background:${host.color}">${initials(host.name)}</span>
            <div class="ps-text"><b>${esc(host.name)} ${isMine ? '♛' : ''}</b><span>${isMine ? 'HOST / あなた' : 'HOST'}</span></div>
            <span class="ready-chip">READY</span>
          </div>
          ${guest ? `
            <div class="player-slot">
              <span class="avatar" style="background:${guest.color}">${initials(guest.name)}</span>
              <div class="ps-text"><b>${esc(guest.name)}</b><span>CHALLENGER / あなた</span></div>
              <span class="ready-chip">READY</span>
            </div>` : `
            <div class="player-slot empty">
              <span class="avatar" style="background:#20283f;color:#7f8db0">?</span>
              <div class="ps-text"><b>挑戦者募集中</b><span>SLOT 2 / OPEN</span></div>
              <span class="ready-chip" style="color:#ffcf9d;border-color:rgba(255,207,107,.25);background:rgba(255,207,107,.06)">WAITING</span>
            </div>`}
        </div>
      </section>

      <aside class="panel room-side-panel">
        <div class="panel-head"><h2>使用デッキ</h2><span class="muted">${deckSize(DECKS[profile.deckId] || DECKS.flame)} + EX</span></div>
        <div class="room-deck-pick" id="roomDeckPick">${deckOpts}</div>
        <div class="room-actions">
          <button class="primary-btn wide" id="startRoomDuel">${startLabel}</button>
          <button class="secondary-btn wide" id="roomSoloBtn">ソロ練習（VS CPU）</button>
        </div>
        <p class="tiny" style="padding:10px 18px 0">${isMine
          ? '開始すると挑戦者が入室し、そのままデュエルが始まります。'
          : 'デュエル開始でホストとの対戦が始まります。'}</p>
      </aside>
    </div>
  `;

  const startBtn = $('startRoomDuel');
  startBtn.addEventListener('click', () => startFromRoom(room));
  $('roomSoloBtn').addEventListener('click', () => startSolo());
  $('copyRoomBtn').addEventListener('click', () => copyCode(room.code));
  $('roomOnlineChip').addEventListener('click', () => toast(`現在 ${online.count} 人がオンライン`, 'good'));

  $('roomDeckPick').addEventListener('click', e => {
    const btn = e.target.closest('[data-deck]');
    if (!btn) return;
    setDeck(btn.dataset.deck);
    renderDeckPicker();
    renderRoomDetail(room);
    sfx('select');
  });
}

function copyCode(code) {
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(code).then(() => toast(`ルームコード ${code} をコピーしました`, 'good')).catch(() => toast(`ルームコード: ${code}`, 'gold'));
  } else {
    toast(`ルームコード: ${code}`, 'gold');
  }
}

function startFromRoom(room) {
  if (!room) return;
  if (room.mine) room = online.myRoom;
  app.roomRef = room;
  app.token += 1;

  let oppName;
  let oppDeckId;
  if (room.mine) {
    const challenger = acceptChallenger() || online.myRoom?.challenger;
    oppName = challenger?.name || 'CHALLENGER';
    oppDeckId = challenger?.deckId || otherDeck();
    toast(`${oppName} がルームに入室しました`, 'good');
  } else {
    oppName = room.host.name;
    oppDeckId = room.host.deckId || otherDeck();
  }

  startDuel({
    oppName,
    oppDeckId,
    modeLabel: room.mine ? 'MY ROOM' : 'ONLINE ROOM',
    roomCode: room.code,
    lp: room.lp || 8000,
  });
}

export function startSolo() {
  const oppName = CPU_NAMES[Math.floor(Math.random() * CPU_NAMES.length)];
  const oppDeckId = CPU_DECKS[Math.floor(Math.random() * CPU_DECKS.length)];
  startDuel({
    oppName,
    oppDeckId,
    modeLabel: 'SOLO',
    roomCode: 'SOLO',
    lp: 8000,
  });
}

function otherDeck() {
  const ids = Object.keys(DECKS).filter(id => id !== profile.deckId);
  return ids[Math.floor(Math.random() * ids.length)] || 'abyss';
}

export function renderLobbyAll() {
  renderProfile();
  renderDeckPicker();
  renderMyRoom();
  renderRecord();
  renderRooms();
  renderOnline();
}

content.text:
Now ui-duel.js. This is the biggest. Need all logic.

Imports:
```js
import { DECKS, DECK_LIST, deckSize, typeLabel } from './cards.js';
import { Duel } from './engine.js';
import { aiChoose } from './ai.js';
import { profile, online, getRoom } from './rooms.js';
import { $, app, esc, toast, showScreen, openModal, closeModal, sleep, cardHTML } from './ui-core.js';
import { captureRects, playEvents, sfx, isSoundOn, toggleSound, flash } from './fx.js';
```

Note core's `cardHTML` uses `app.duel`.

Init:
```js
let aiRunning=false, bannerTimer=null, soundBound=false;
export function initDuel() {
  $('leaveDuelBtn').onclick = leaveDuel;
  $('logBtn').onclick = openLogModal;
  $('soundBtn').onclick = () => { const on=toggleSound(); updateSoundBtn(); };
  $('extraBtn').onclick = openExtraModal;
  $('board').addEventListener('click', onBoardClick);
  $('hand').addEventListener('click', onHandClick);
  $('actionTray').addEventListener('click', onTrayClick);
  $('oppLpBlock').addEventListener('click', onDirectAttack);
  $('youPiles').addEventListener('click', onPileClick);
  $('oppPiles').addEventListener('click', onPileClick);
  $('extraBtn').addEventListener('click', openExtraModal); // duplicate if already
  updateSoundBtn();
  document.addEventListener('keydown', e => {
    if (app.screen!=='duel') return;
    if (e.key===' ' && !app.duel?.winner && !app.busy) { e.preventDefault(); endTurn(); }
  });
}
```
Don't duplicate extraBtn binding.

`updateSoundBtn`: text '♪' on, '×' off; className? Use `title`.

`startDuel(config)`:
```js
export function startDuel({ oppName, oppDeckId, modeLabel='SOLO', roomCode='—', lp=8000 }) {
  const deckId = DECKS[profile.deckId] ? profile.deckId : 'flame';
  const d = new Duel({playerName: profile.name, oppName, deckId, oppDeckId, lp, mode:modeLabel});
  app.duel = d;
  app.sel=null; app.busy=false; app.resultShown=false; app.deal=true;
  app.token += 1;
  app.lastConfig={oppName, oppDeckId, modeLabel, roomCode, lp};
  aiRunning=false;
  showScreen('duel');
  $('duelModeLabel').textContent=modeLabel;
  $('duelRoomLabel').textContent = roomCode==='SOLO' ? 'SOLO TRAINING' : `ROOM ${roomCode}`;
  renderDuel();
  showTurnBanner(d.turn);
  setTimeout(()=>{app.deal=false;}, 900);
  if (d.turn==='opp') setTimeout(()=>runAiTurn(), 950);
  toast(`デュエル開始 — ${oppName}`, 'gold');
}
```
`app.token` increments once here; `startFromRoom` also increments before calling → double; okay token used for invalidation. Remove increment in lobby? It increments before start; fine.

`renderDuel`:
```js
export function renderDuel() {
  const d=app.duel; if(!d) return;
  renderSide('opp'); renderSide('you'); renderFieldSlots(); renderEmz();
  renderNames(); renderLP(); renderPiles(); renderHand(); renderTray(); renderLog(); renderTurnUI(); renderSound? 
  // deal animation
  if (app.deal) {...}
  app.renderDuel = renderDuel; // for Escape handler
}
```
Set `app.renderDuel = renderDuel` in init instead.

`renderSide`:
```js
function renderSide(side) {
  const d=app.duel;
  const m = d.field[side].monster.map((e,i)=>zoneHTML(side,'monster',i,e)).join('');
  const s = d.field[side].spell.map((e,i)=>zoneHTML(side,'spell',i,e)).join('');
  $(side+'Rows').innerHTML = `<div class="zone-row">${m}</div><div class="zone-row">${s}</div>`;
}
```
For opp rows should be spell row then monster row. CSS order in HTML: I want top spell, bottom monster (monster nearest center). `.rows` is inside side; opp side is above center, so bottom of opp side is nearest center → monster should be second row. So `spell row` first, `monster` second. For you side below center, monster nearest center → first row. So:
```js
$(side+'Rows').innerHTML = side==='opp' ? `<div class="zone-row">${s}</div><div class="zone-row">${m}</div>` : `<div class="zone-row">${m}</div><div class="zone-row">${s}</div>`;
```
Good.

`renderEmz`: zoneHTML with owner side.

`renderNames`: `$('youName')`, `$('oppName')`, `$('youAvatar')`, `$('oppAvatar')` text/initials and background. `initials` import from rooms. Opp tag `d.mode` maybe; show 'ONLINE DUELIST' or 'CPU'. Set oppTag: `d.mode==='SOLO'?'SOLO CPU':d.mode`. You tag 'CHALLENGER'.

`zoneHTML`/`zoneState`/`canDropOn` as designed.

`zoneNumber`.

`renderLP`:
- startLp from d.
- percent `Math.min(100, lp/d.startLp*100)`.
- Use text with locale.
- Block danger.

`renderPiles`:
- `pileHTML(side)`.

`renderHand` with deal.
`renderTray`.
`renderLog`.
`renderTurnUI`.
`renderSoundBtn`.

Action tray implementation carefully.

```js
function chip(card) {
  const color = ATTR? need import ATTR or use cardAccent. Use `cardAccent` from cards. Import.
}
```
Import `cardAccent` maybe. Let's import `ATTR` from cards for colors. Use `ATTR[card.attribute].color`.

`btn`.

Default:
```js
const canEnd = d.turn==='you' && !app.busy && !d.winner;
const exOk = canEx();
html = `<span class="tray-hint"><i></i>${d.winner?'デュエル終了':'カードをタップして選択'}</span><span class="tray-spacer"></span>
  <button class="tray-btn" data-tray="extra" ${exOk?'':'disabled'}>EX召喚</button>
  <button class="tray-btn gold" data-tray="end" ${canEnd?'':'disabled'}>ターン終了</button>`;
```
If busy: hint "処理中…"; buttons disabled.
If turn opp: hint "相手のターン — カードが動きます".
If winner: hint "デュエル終了"; button "結果を見る" data-tray="result".

Selected hand:
```js
const c=sel.card;
const isMonster...
html = chipHTML(c);
if (sel.action) { hint `配置先のゾーンを選択`; + cancel }
else {
 if monster: btn 召喚 primary disabled=summoned ; btn セット disabled=summoned; 
   if tributes need: hint `生贄 ${need}体（ATKが低い順に自動）`
 if spell: btn 発動 primary; if not field: btn セット
 if trap: btn セット primary
 btn 詳細; btn キャンセル
}
```
Disable summon if `d.flags.summoned`; if ownMonsters < need, disabled with title.

Selected field:
```js
const entry = sel.kind==='emz'? d.emz[sel.idx] : d.field.you[sel.kind][sel.idx] (field is object)
```
Use d.entryAt('you', sel.kind, sel.idx).
- Monster:
  - chip with atk/def/pos.
  - if attackReady: hint "攻撃対象をタップ / 相手LPで直接攻撃" + cancel attack + detail.
  - else:
    - canAtk = turn you && !entry.attacked && entry.position==='atk' && !entry.faceDown && !busy
    - btn 攻撃 primary if canAtk
    - position change if entry.summonedTurn !== d.turnNo:
      - if faceDown: buttons 攻撃表示 / 守備表示 (flip)
      - else: button to opposite position.
    - detail, cancel
  - if attacked: hint.
- Spell/trap:
  - faceDown spell: 発動; detail; cancel.
  - trap: hint auto; detail; cancel.
  - field: detail.

`onTrayClick` handles.

`canEx()`:
```js
const d=app.duel;
return d && d.turn==='you' && !d.flags.extraSummoned && d.extra.you.length>0 && d.ownMonsters('you').length>=2 && d.emz.some(e=>!e) && !app.busy;
```

`onHandClick`:
```js
if (!d || app.busy || d.winner || d.turn!=='you') return;
const el=e.target.closest('.hand-card'); if(!el) return;
const uid=el.dataset.uid;
if (app.sel?.type==='hand' && app.sel.uid===uid) { app.sel=null; renderDuel(); return; }
const card=d.hand.you.find(c=>c.uid===uid); if(!card) return;
app.sel={type:'hand', uid, card, action:null};
sfx('select'); renderDuel();
```

`onBoardClick`:
As above.

`selectField`:
```js
const entry=d.entryAt('you',kind,idx); if(!entry)return;
app.sel={type:'field', side:'you', kind, idx, card:entry.card, attackReady:false};
sfx('select'); renderDuel();
```

`onDirectAttack`: if sel attackReady and no opp monsters → `perform({type:'attack',kind:sel.kind,idx:sel.idx,target:{kind:'direct'}})`.

`onPileClick`: e.target.closest('[data-pile]') → openPile(side,type).

`perform` as designed. Need to ensure `renderTray` updated when busy toggles before await. In player path: set busy true, renderDuel before? We capture, run engine, render. During animation tray shows busy because renderTray reads app.busy=true. Good.

But `perform` for player: app.busy=true, then `runEngine`, then render. If engine throws, set busy false, renderDuel to restore tray. Do that.

After animation, app.busy=false; if no winner and turn still you → renderDuel to enable. Else if opp → runAiTurn. Don't renderDuel before AI? runAiTurn does.

`runEngine` for player includes `end` action.

`onTrayClick`:
- read `data-tray`.
- cancel etc.
- For end: if busy/turn not you → return. perform.
- detail uses sel card; for field entry, side/pass.
- `extra` opens modal.
- `result` showResult (if winner).
- `sound` no.

`position` actions use `sel.kind`; for emz.

`extra` modal:
```js
function openExtraModal() {
  const d=app.duel;
  const can = ...;
  const rows = d.extra.you.map((c,i)=>`<button class="modal-list-card" data-ex="${i}" ${can?'':'disabled'}>...`).join('');
  const body=openModal(`
   <div class="modal-title">EX召喚</div>
   <p class="modal-sub">モンスター2体を生贄に、中央のEXゾーンへ特殊召喚。1ターンに1回。</p>
   ${can?'':`<div class="detail-note">条件未達：モンスター2体以上 / EXゾーン空き / 1ターン1回 / 自分のターン</div>`}
   <div class="modal-list">${rows || '<p class="tiny">EXデッキが空です</p>'}</div>
  `);
  body.querySelectorAll('[data-ex]').forEach(btn=>btn.onclick=()=>{
    if (!can) return;
    const card=d.extra.you[Number(btn.dataset.ex)];
