}
```
`can` computed before.

`openPile(side,type)`:
- type deck: list count and card backs (limited).
- type extra: extra cards.
- gy/banished: cards.
- Modal list rows with miniCardHTML and stats.
- Use `typeLabel`.
- Extra rows not clickable.
```js
const label = {deck:'デッキ',gy:'墓地',banished:'除外',extra:'EXデッキ'}[type];
const cards = ...
if deck: show 40 card backs? just note.
rows = cards.slice(0,60).map((c,i)=>`<button class="modal-list-card" data-pileidx="${i}">...`).join('');
```
Bind detail view (except deck): `openCardDetail(cards[i])`.

`openCardDetail(card, entry, side='you')`:
- compute atk/def.
- type meta.
- openModal with `.card-detail`.
- For non-monster hide stats? Show `—`.
- Card face uses `cardHTML(card,{entry,side,interactive:false})`; but `.detail-card` wrapper needs class to size. Wrap `<div class="detail-card" style="width:170px;height:238px">`; CSS `.card-detail .detail-card` already width/height; inside `.card` width 100% height 100%.
- For hand card no entry; atk base.

`openLogModal`: all logs; scroll to bottom after open:
```js
const body=openModal(`
 <div class="modal-title">デュエルログ</div><p class="modal-sub">T${d.turnNo} · ${d.logs.length} entries</p>
 <div class="log-full">${d.logs.map(l=>`<div class="log-full-row tone-${l.tone}"><span>T${l.turn}</span><p>${esc(l.text)}</p></div>`).join('')}</div>`);
body.querySelector('.log-full').scrollTop = ...
```
Add CSS `.log-full`.

`leaveDuel`:
```js
function leaveDuel() {
  if (!app.duel) { exit(); return; }
  if (app.duel.winner) { exit(); return; }
  const body=openModal(`...`, {locked:false});
  body.querySelector('#confirmLeave').onclick=()=>{closeModal(true); exit();};
  ...
}
function exitDuel() {
  app.token+=1; app.duel=null; app.sel=null; app.busy=false; aiRunning=false;
  closeModal(true);
  app.onExitDuel?.();
}
```
`app.onExitDuel` set by lobby init. If not set, showScreen('lobby').

`showResult`:
```js
function showResult() {
  const d=app.duel; if(!d) return;
  const win=d.winner==='you';
  const total=d.turnNo;
  const body=openModal(`
   <div class="result-screen">
     <p class="result-eyebrow">DUEL ${win?'WON':'LOST'} · ${esc(d.mode)}</p>
     <h2 class="result-title ${win?'win':'lose'}">${win?'VICTORY':'DEFEAT'}</h2>
     <p class="modal-sub">${d.overReason||''}</p>
     <div class="result-lp">${d.lp.you} <span>LP</span> — ${d.lp.opp} <span>LP</span></div>
     <div class="result-stats">
       <div><span>TURNS</span><b>${d.turnNo}</b></div>
