     </div>
     <div class="modal-actions" style="justify-content:center">
       <button class="primary-btn" data-result="rematch">もう一度</button>
       <button class="secondary-btn" data-result="lobby">ロビーへ</button>
     </div>
   </div>
  `, {locked:true});
  body.querySelectorAll('[data-result]').forEach(btn=>btn.onclick=()=>{
    const action=btn.dataset.result;
    closeModal(true);
    if(action==='rematch'){ const c=app.lastConfig; if(c) startDuel(c); else exitDuel(); }
    else exitDuel();
  });
}
```
Result modal locked prevents backdrop close.

`onDuelEnd`:
```js
function onDuelEnd() {
  if (!app.duel || app.resultShown) return;
  app.resultShown=true;
  const win=app.duel.winner==='you';
  addResult(win?'win':'loss');
  setTimeout(()=>{ if(app.duel) showResult(); }, 650);
}
```
Import addResult.

`showTurnBanner(side)`:
- element hidden false; classes.
- span T; b label.
- timeout hide 1100.
- sfx? maybe.

`renderTurnUI`:
```js
const d=app.duel;
const pill=$('turnPill');
pill.classList.toggle('opp', d.turn==='opp'&&!d.winner);
pill.classList.toggle('over', !!d.winner);
pill.querySelector('span').textContent = d.winner?'DUEL OVER': d.turn==='you'?'YOUR TURN':'OPPONENT TURN';
