async function perform(action, { ai=false } = {}) {
  const d=app.duel;
  if (!d || d.winner) return false;
  const side=ai?'opp':'you';
  if (!ai) {
    if (app.busy || d.turn!=='you') return false;
    app.busy=true;
  }
  const captured=captureRects();
  let events;
  try { events=runEngine(action, side); }
  catch(err) {
    if(!ai){ app.busy=false; toast(err.message||'実行できません','bad'); renderDuel(); sfx('click'); }
    return false;
  }
  app.sel=null;
  renderDuel();
  await playEvents(events, captured, {duel:d});
  if (app.duel!==d) return false;
  if (!ai) {
    app.busy=false;
    if (d.winner) onDuelEnd();
    else if (d.turn==='opp') { await sleep(180); runAiTurn(); }
    else { renderDuel(); }
  }
  return true;
}
