async function runAiTurn() {
  const d=app.duel;
  if (!d || aiRunning || d.winner) return;
  const token=app.token;
  aiRunning=true; app.busy=true; app.sel=null;
  renderDuel();
  showTurnBanner('opp');
  await sleep(800);
  let guard=0;
  while (app.duel===d && app.token===token && !d.winner && d.turn==='opp' && guard++<50) {
    const action=aiChoose(d,'opp');
    if (!action || action.type==='end') { await perform({type:'end'},{ai:true}); break; }
    const ok=await perform(action,{ai:true});
    if(!ok){ await perform({type:'end'},{ai:true}); break; }
    await sleep(340);
  }
  aiRunning=false;
  if (app.duel!==d || app.token!==token) return;
  app.busy=false;
  renderDuel();
  if (d.winner) onDuelEnd();
  else { showTurnBanner('you'); toast('あなたのターン','good'); }
}
```
