/* Duel board rendering, start duel, tray, turn banner. */

import { ATTR, DECKS } from './cards.js';
import { Duel } from './engine.js';
import { profile, avatarColor, initials } from './rooms.js';
import {
  $, app, esc, cardHTML, showScreen, toast, sleep,
} from './ui-core.js';
import { sfx } from './fx.js';

/* ---------------- start ---------------- */
export function startDuel({ oppName, oppDeckId, modeLabel = 'SOLO', roomCode = 'SOLO', lp = 8000 }) {
  const deckId = DECKS[profile.deckId] ? profile.deckId : 'flame';
  const duel = new Duel({
    playerName: profile.name,
    oppName,
    deckId,
    oppDeckId: DECKS[oppDeckId] ? oppDeckId : 'abyss',
    lp,
    mode: modeLabel,
  });

  app.token += 1;
  app.duel = duel;
  app.sel = null;
  app.busy = false;
  app.resultShown = false;
  app.deal = true;
  app.lastConfig = { oppName, oppDeckId, modeLabel, roomCode, lp };

  showScreen('duel');
  $('duelModeLabel').textContent = modeLabel;
  $('duelRoomLabel').textContent = roomCode === 'SOLO' ? 'SOLO TRAINING' : `ROOM ${roomCode}`;
  $('turnBanner').hidden = true;

  renderDuel();
  showTurnBanner(duel.turn);
  toast(`デュエル開始 — ${oppName}`, 'gold');
  setTimeout(() => { app.deal = false; }, 1100);

  if (duel.turn === 'opp') setTimeout(() => app.runAiTurn?.(), 1050);
}

/* ---------------- render ---------------- */
export function renderDuel() {
  const d = app.duel;
  if (!d) return;
  renderNames(d);
  renderSide('opp', d);
  renderSide('you', d);
  $('oppFieldSlot').innerHTML = zoneHTML('opp', 'field', 0, d.field.opp.field);
  $('youFieldSlot').innerHTML = zoneHTML('you', 'field', 0, d.field.you.field);
  renderEmz(d);
  renderLP(d);
  renderPiles(d);
  renderHand(d);
  renderLog(d);
  renderTurn(d);
  renderTray(d);
  $('oppLpBlock').classList.toggle(
    'targetable',
    !!(app.sel?.type === 'field' && app.sel.attackReady && d.ownMonsters('opp').length === 0 && !d.winner),
  );
  $('handTip').textContent = d.winner
    ? 'デュエル終了'
    : app.busy ? '処理中…'
      : d.turn === 'opp' ? '相手のターン'
        : app.sel?.action ? '光っているゾーンを選択'
          : 'カードをタップして選択';
}

function renderNames(d) {
  $('youName').textContent = d.names.you;
  $('youTag').textContent = 'CHALLENGER';
  $('oppName').textContent = d.names.opp;
  $('oppTag').textContent = d.mode === 'SOLO' ? 'SOLO CPU' : 'ONLINE DUELIST';
  const ya = $('youAvatar');
  ya.textContent = initials(d.names.you);
  ya.style.background = `linear-gradient(140deg, ${avatarColor(d.names.you)}, #6c8dff)`;
  const oa = $('oppAvatar');
  oa.textContent = initials(d.names.opp);
  oa.style.background = `linear-gradient(140deg, ${avatarColor(d.names.opp)}, #ff5ca8)`;
}

function renderSide(side, d) {
  const monsters = d.field[side].monster.map((e, i) => zoneHTML(side, 'monster', i, e)).join('');
  const spells = d.field[side].spell.map((e, i) => zoneHTML(side, 'spell', i, e)).join('');
  const m = `<div class="zone-row">${monsters}</div>`;
  const s = `<div class="zone-row">${spells}</div>`;
  $(side + 'Rows').innerHTML = side === 'opp' ? s + m : m + s;
}

function renderEmz(d) {
  $('emzArea').innerHTML = [0, 1].map(i => {
    const entry = d.emz[i];
    const owner = entry?.owner || 'you';
    return `<div class="emz-slot-wrap">
      ${zoneHTML(owner, 'emz', i, entry)}
      <span class="emz-caption">EX ${i + 1}</span>
    </div>`;
  }).join('');
}

function zoneNumber(side, kind, idx) {
  if (kind === 'monster') return (side === 'you' ? 1 : 12) + idx;
  if (kind === 'spell') return (side === 'you' ? 6 : 17) + idx;
  if (kind === 'field') return side === 'you' ? 11 : 22;
  return 23 + idx;
}

function zoneHTML(side, kind, idx, entry) {
  const d = app.duel;
  const znum = zoneNumber(side, kind, idx);
  const state = zoneState(side, kind, idx, entry);
  const cls = ['zone'];
  if (kind === 'field') cls.push('zone-field');
  if (kind === 'emz') cls.push('zone-emz');
  if (state.valid) cls.push('valid');
  if (state.targetable) cls.push('targetable');
  if (state.selected) cls.push('selected');
  if (entry) cls.push('hoverable');

  const emptyLabel = kind === 'monster' ? ['MON', '+'] : kind === 'spell' ? ['S/T', '+'] : kind === 'field' ? ['FIELD', 'F'] : ['EX', 'EX'];
  const body = entry
    ? cardHTML(entry.card, { entry, side, interactive: true })
    : `<div class="zone-empty-label"><b>${emptyLabel[1]}</b>${emptyLabel[0]}</div>`;

  return `<div class="${cls.join(' ')}" data-side="${side}" data-kind="${kind}" data-idx="${idx}" role="button" aria-label="ゾーン${znum} ${kind}">
    <span class="znum">Z${String(znum).padStart(2, '0')}</span>${body}
  </div>`;
}

function zoneState(side, kind, idx, entry) {
  const d = app.duel;
  let valid = false;
  let targetable = false;
  let selected = false;
  if (!d) return { valid, targetable, selected };

  valid = canDropOn(side, kind, idx);
  if (app.sel?.type === 'field' && app.sel.attackReady) {
    if (kind === 'emz') targetable = !!entry && entry.owner === 'opp';
    else if (side === 'opp' && kind === 'monster' && entry) targetable = true;
  }
  if (app.sel?.type === 'field' && !app.sel.attackReady) {
    if (kind === 'emz') selected = !!entry && entry.owner === 'you' && app.sel.kind === 'emz' && app.sel.idx === idx;
    else selected = side === 'you' && app.sel.kind === kind && app.sel.idx === idx;
  }
  return { valid, targetable, selected };
}

export function canDropOn(side, kind, idx) {
  const d = app.duel;
  if (!d || !app.sel || side !== 'you' || d.turn !== 'you' || app.busy || d.winner) return false;
  const empty = kind === 'emz' ? !d.emz[idx] : !d.entryAt('you', kind, idx);
  if (!empty) return false;
  if (app.sel.type === 'extra') return kind === 'emz';
  if (app.sel.type !== 'hand' || !app.sel.action) return false;
  if (app.sel.action === 'summon' || app.sel.action === 'set') return kind === 'monster' && app.sel.card.kind === 'monster';
  if (app.sel.action === 'setSpell') return kind === 'spell';
  return false;
}

/* ---------------- LP / piles / hand ---------------- */
function renderLP(d) {
  for (const side of ['you', 'opp']) {
    const lp = d.lp[side];
    const pct = Math.max(0, Math.min(100, (lp / Math.max(1, d.startLp)) * 100));
    $(side + 'Lp').textContent = lp.toLocaleString('en-US');
    $(side + 'LpFill').style.width = `${pct}%`;
    $(side + 'LpBlock').classList.toggle('danger', lp <= 2000);
  }
}

function pileHTML(side, type, label, count, cls) {
  return `<button class="pile ${cls}" data-pile="${type}" data-side="${side}" title="${label}">
    <span>${label}</span><b>${count}</b>
  </button>`;
}

function renderPiles(d) {
  for (const side of ['you', 'opp']) {
    $(side + 'Piles').innerHTML =
      pileHTML(side, 'deck', 'DECK', d.deck[side].length, 'deck') +
      pileHTML(side, 'gy', 'GY', d.gy[side].length, 'gy') +
      pileHTML(side, 'extra', 'EX', d.extra[side].length, 'extra') +
      pileHTML(side, 'banished', 'BAN', d.banished[side].length, 'banished');
  }
}

function renderHand(d) {
  $('handCount').textContent = d.hand.you.length;
  $('exCount').textContent = d.extra.you.length;
  const cards = d.hand.you;
  if (!cards.length) {
    $('hand').innerHTML = '<div class="hand-empty">手札なし<br>相手のターンを待つ</div>';
    return;
  }
  $('hand').innerHTML = cards.map(c => {
    const selected = app.sel?.type === 'hand' && app.sel.uid === c.uid;
    return `<button class="hand-card ${selected ? 'selected' : ''}" data-uid="${c.uid}" aria-label="${esc(c.name)}">
      ${cardHTML(c, { hand: true, interactive: false })}
    </button>`;
  }).join('');

  if (app.deal) {
    [...$('hand').children].forEach((el, i) => {
      el.classList.add('anim-draw');
      el.style.animationDelay = `${i * 65}ms`;
    });
    setTimeout(() => {
      [...$('hand').children].forEach(el => {
        el.classList.remove('anim-draw');
        el.style.animationDelay = '';
      });
    }, 1000);
  }
}

/* ---------------- log / turn / tray ---------------- */
function renderLog(d) {
  const logs = d.logs.slice(-3);
  $('logStrip').innerHTML = logs.map(l => `<div class="log-item"><span>${esc(l.text)}</span></div>`).join('')
    + `<span class="log-turn">T${d.turnNo} · ${d.logs.length} LOG</span>`;
}

function renderTurn(d) {
  const pill = $('turnPill');
  pill.classList.toggle('opp', !d.winner && d.turn === 'opp');
  pill.classList.toggle('over', !!d.winner);
  pill.querySelector('span').textContent = d.winner ? 'DUEL OVER' : d.turn === 'you' ? 'YOUR TURN' : 'OPPONENT TURN';
  $('turnNo').textContent = `T${d.turnNo}`;
}

function chipHTML(card) {
  const color = ATTR[card.attribute]?.color || '#4de3ff';
  return `<span class="tray-card-name" style="--accent:${color}"><span class="dot"></span><span>${esc(card.name)}</span></span>`;
}

function btn(label, key, cls = '', disabled = false) {
  return `<button class="tray-btn ${cls}" data-tray="${key}" ${disabled ? 'disabled' : ''}>${label}</button>`;
}

function canEx() {
  const d = app.duel;
  return !!d && d.turn === 'you' && !app.busy && !d.winner && !d.flags.extraSummoned
    && d.extra.you.length > 0 && d.ownMonsters('you').length >= 2 && d.emz.some(e => !e);
}

function renderTray(d) {
  const tray = $('actionTray');
  if (!d) { tray.innerHTML = ''; return; }
  if (d.winner) {
    tray.innerHTML = `<span class="tray-hint"><i></i>デュエル終了 — ${d.winner === 'you' ? '勝利' : '敗北'}</span><span class="tray-spacer"></span>${btn('結果を見る', 'result', 'gold')}`;
    return;
  }
  if (app.busy) {
    tray.innerHTML = `<span class="tray-hint"><i></i>${d.turn === 'you' ? 'カードを処理中…' : '相手が考えています…'}</span><span class="tray-spacer"></span>${btn('EX召喚', 'none', '', true)}${btn('ターン終了', 'none', 'gold', true)}`;
    return;
  }
  if (d.turn !== 'you') {
    tray.innerHTML = `<span class="tray-hint"><i></i>相手のターン — カードが動きます</span><span class="tray-spacer"></span>${btn('EX召喚', 'none', '', true)}${btn('ターン終了', 'none', 'gold', true)}`;
    return;
  }

  const sel = app.sel;
  if (!sel) {
    tray.innerHTML = `<span class="tray-hint"><i></i>カードをタップして選択</span><span class="tray-spacer"></span>
      ${btn('EX召喚', 'extra', '', !canEx())}${btn('ターン終了', 'end', 'gold')}`;
    return;
  }

  if (sel.type === 'hand') {
    const c = sel.card;
    if (sel.action) {
      const label = sel.action === 'setSpell' ? '魔法・罠ゾーンを選択' : 'モンスターゾーンを選択';
      tray.innerHTML = `${chipHTML(c)}<span class="tray-hint"><i></i>${label}</span><span class="tray-spacer"></span>${btn('キャンセル', 'cancel')}`;
      return;
    }
    if (c.kind === 'monster') {
      const need = d.tributesNeeded(c.level);
      const enough = d.ownMonsters('you').length >= need;
      const dis = d.flags.summoned || !enough;
      const note = d.flags.summoned ? 'このターン召喚済み' : !enough ? `生贄${need}体が必要` : need ? `生贄 ${need}体（自動）` : '召喚可';
      tray.innerHTML = `${chipHTML(c)}
        ${btn('召喚', 'summon', 'primary', dis)}${btn('セット', 'set', '', dis)}
        ${btn('詳細', 'detail')}<span class="tray-spacer"></span><span class="tray-turn">${note}</span>`;
      return;
    }
    if (c.kind === 'spell') {
      const canSet = c.spellType !== 'field';
      tray.innerHTML = `${chipHTML(c)}${btn('発動', 'activate', 'primary')}
        ${canSet ? btn('セット', 'set') : ''}${btn('詳細', 'detail')}
        <span class="tray-spacer"></span><span class="tray-turn">魔法${c.spellType === 'field' ? '／フィールド' : ''}</span>`;
      return;
    }
    tray.innerHTML = `${chipHTML(c)}${btn('セット', 'set', 'primary')}${btn('詳細', 'detail')}<span class="tray-spacer"></span><span class="tray-turn">罠</span>`;
    return;
  }

  if (sel.type === 'extra') {
    tray.innerHTML = `${chipHTML(sel.card)}<span class="tray-hint"><i></i>空いているEXゾーンを選択（生贄2体）</span><span class="tray-spacer"></span>${btn('キャンセル', 'cancel')}`;
    return;
  }

  if (sel.type === 'field') {
    const entry = d.entryAt('you', sel.kind, sel.idx);
    if (!entry) { app.sel = null; renderTray(d); return; }
    const card = entry.card;

    if (card.kind === 'monster') {
      if (sel.attackReady) {
        tray.innerHTML = `${chipHTML(card)}<span class="tray-hint"><i></i>攻撃対象をタップ（相手LPで直接攻撃）</span><span class="tray-spacer"></span>${btn('やめる', 'cancelAttack')}${btn('詳細', 'detail')}`;
        return;
      }
      const canAtk = !entry.faceDown && entry.position === 'atk' && !entry.attacked;
      const canPos = entry.summonedTurn !== d.turnNo;
      const posBtn = canPos
        ? (entry.position === 'atk' && !entry.faceDown
          ? btn('守備表示', 'positionDef')
          : btn('攻撃表示', 'positionAtk'))
        : '';
      const note = entry.attacked ? '攻撃済み' : entry.faceDown ? 'セット' : entry.position === 'atk' ? `ATK ${d.atkOf('you', entry)}` : `DEF ${d.defOf('you', entry)}`;
      tray.innerHTML = `${chipHTML(card)}
        ${canAtk ? btn('攻撃', 'attack', 'primary') : ''}
        ${posBtn}${btn('詳細', 'detail')}${btn('キャンセル', 'cancel')}
        <span class="tray-spacer"></span><span class="tray-turn">${note}</span>`;
      return;
    }

    if (card.kind === 'spell' && entry.faceDown) {
      tray.innerHTML = `${chipHTML(card)}${btn('発動', 'activateSet', 'primary')}${btn('詳細', 'detail')}${btn('キャンセル', 'cancel')}<span class="tray-spacer"></span><span class="tray-turn">伏せ魔法</span>`;
      return;
    }
    if (card.kind === 'trap') {
      tray.innerHTML = `${chipHTML(card)}<span class="tray-hint"><i></i>伏せ罠 — 相手の攻撃時に自動発動</span><span class="tray-spacer"></span>${btn('詳細', 'detail')}${btn('キャンセル', 'cancel')}`;
      return;
    }
    tray.innerHTML = `${chipHTML(card)}${btn('詳細', 'detail')}${btn('キャンセル', 'cancel')}<span class="tray-spacer"></span><span class="tray-turn">${card.spellType === 'field' ? 'フィールド魔法 発動中' : 'セット済み'}</span>`;
  }
}

/* ---------------- banner ---------------- */
export function showTurnBanner(side) {
  const d = app.duel;
  const el = $('turnBanner');
  if (!d || !el) return;
  el.hidden = false;
  el.className = `turn-banner ${side === 'you' ? 'you' : 'opp'}`;
  el.querySelector('span').textContent = `TURN ${d.turnNo}`;
  el.querySelector('b').textContent = side === 'you' ? 'YOUR TURN' : 'OPPONENT TURN';
  clearTimeout(bannerTimer);
  bannerTimer = setTimeout(() => { el.hidden = true; }, 1150);
  sfx('select');
}

let bannerTimer = null;

/* Duel interactions: input, engine actions, AI loop, modals, results. */

import { DECKS, typeLabel } from './cards.js';
import { aiChoose } from './ai.js';
import { profile, addResult } from './rooms.js';
import {
  $, app, esc, toast, openModal, closeModal, sleep, miniCardHTML, showScreen,
} from './ui-core.js';
import { captureRects, playEvents, sfx, isSoundOn, toggleSound } from './fx.js';
import { startDuel, renderDuel, canDropOn } from './duel-render.js';

export { startDuel };

let aiRunning = false;

export function initDuel() {
  app.renderDuel = renderDuel;
  app.runAiTurn = runAiTurn;

  $('leaveDuelBtn').addEventListener('click', confirmLeave);
  $('logBtn').addEventListener('click', openLogModal);
  $('soundBtn').addEventListener('click', e => {
    const on = toggleSound();
    updateSoundBtn();
    toast(on ? 'サウンド ON' : 'サウンド OFF', on ? 'good' : '');
  });
  $('extraBtn').addEventListener('click', openExtraModal);
  $('board').addEventListener('click', onBoardClick);
  $('hand').addEventListener('click', onHandClick);
  $('actionTray').addEventListener('click', onTrayClick);
  $('oppLpBlock').addEventListener('click', onDirectAttack);
  $('youPiles').addEventListener('click', onPileClick);
  $('oppPiles').addEventListener('click', onPileClick);

  $('turnBanner').hidden = true;
  updateSoundBtn();

  document.addEventListener('keydown', e => {
    if (app.screen !== 'duel' || e.key !== ' ' || e.target.tagName === 'INPUT') return;
    if (document.activeElement && document.activeElement.tagName === 'BUTTON') return;
    if (app.duel && !app.duel.winner && !app.busy) {
      e.preventDefault();
      perform({ type: 'end' });
    }
  });
}

function updateSoundBtn() {
  const b = $('soundBtn');
  if (!b) return;
  b.textContent = isSoundOn() ? '♪' : '×';
  b.style.opacity = isSoundOn() ? '1' : '.5';
  b.title = isSoundOn() ? 'サウンド ON' : 'サウンド OFF';
}

/* ---------------- input ---------------- */
function onHandClick(e) {
  const d = app.duel;
  const el = e.target.closest('.hand-card');
  if (!d || !el || app.busy || d.winner || d.turn !== 'you') return;
  const uid = el.dataset.uid;
  if (app.sel?.type === 'hand' && app.sel.uid === uid) {
    app.sel = null;
    renderDuel();
    return;
  }
  const card = d.hand.you.find(c => c.uid === uid);
  if (!card) return;
  app.sel = { type: 'hand', uid, card, action: null };
  sfx('select');
  renderDuel();
}

function onBoardClick(e) {
  const zone = e.target.closest('.zone');
  if (!zone || !app.duel) return;
  handleZone(zone.dataset.side, zone.dataset.kind, Number(zone.dataset.idx));
}

function handleZone(side, kind, idx) {
  const d = app.duel;
  if (!d) return;
  if (d.winner) { if (!app.busy) toast('デュエルは終了しています', 'bad'); return; }
  if (app.busy) return;

  const entry = kind === 'emz' ? d.emz[idx] : d.entryAt(side, kind, idx);

  if (app.sel?.type === 'field' && app.sel.attackReady) {
    if (kind === 'emz') {
      if (entry && entry.owner === 'opp') { doAttack({ kind: 'emz', idx }); return; }
      if (entry && entry.owner === 'you') return;
    } else if (side === 'opp' && kind === 'monster' && entry) {
      doAttack({ kind: 'monster', idx });
      return;
    } else if (side === 'opp' && entry) {
      toast('魔法・罠は攻撃対象にできません', 'bad');
      return;
    }
  }

  if (side === 'you' && app.sel && canDropOn('you', kind, idx)) {
    doDrop(kind, idx);
    return;
  }

  if (kind === 'emz') {
    if (!entry) { app.sel = null; renderDuel(); return; }
    if (entry.owner === 'you') selectField('you', 'emz', idx);
    else openCardDetail(entry.card, entry, 'opp');
    return;
  }

  if (entry && side === 'you') { selectField('you', kind, idx); return; }
  if (entry && side === 'opp') { openCardDetail(entry.card, entry, 'opp'); return; }

  app.sel = null;
  renderDuel();
}

function selectField(side, kind, idx) {
  const d = app.duel;
  const entry = d.entryAt(side, kind, idx);
  if (!entry) return;
  app.sel = { type: 'field', side, kind, idx, card: entry.card, attackReady: false };
  sfx('select');
  renderDuel();
}

function doDrop(kind, idx) {
  const sel = app.sel;
  if (!sel) return;
  if (sel.type === 'extra') {
    perform({ type: 'extra', uid: sel.uid, slot: idx });
    return;
  }
  if (sel.type !== 'hand') return;
  if (sel.card.kind === 'monster') {
    perform({ type: 'summon', uid: sel.uid, zone: idx, mode: sel.action === 'set' ? 'set' : 'atk' });
  } else {
    perform({ type: 'set', uid: sel.uid, zone: idx });
  }
}

function doAttack(target) {
  const sel = app.sel;
  if (!sel || sel.type !== 'field') return;
  perform({ type: 'attack', kind: sel.kind, idx: sel.idx, target });
}

function onDirectAttack() {
  const d = app.duel;
  if (!d || app.busy || d.winner) return;
  const sel = app.sel;
  if (!sel || sel.type !== 'field' || !sel.attackReady) return;
  if (d.ownMonsters('opp').length > 0) {
    toast('相手モンスターがいるため直接攻撃できません', 'bad');
    return;
  }
  doAttack({ kind: 'direct' });
}

/* ---------------- tray ---------------- */
function onTrayClick(e) {
  const b = e.target.closest('[data-tray]');
  if (!b || !app.duel) return;
  const t = b.dataset.tray;
  const d = app.duel;
  const sel = app.sel;

  switch (t) {
    case 'end':
      if (d.turn === 'you' && !app.busy) perform({ type: 'end' });
      break;
    case 'summon':
      if (sel?.type === 'hand') { sel.action = 'summon'; renderDuel(); }
      break;
    case 'set':
      if (sel?.type === 'hand') {
        sel.action = sel.card.kind === 'monster' ? 'set' : 'setSpell';
        renderDuel();
      }
      break;
    case 'activate':
      if (sel?.type === 'hand') perform({ type: 'activateSpell', uid: sel.uid });
      break;
    case 'activateSet':
      if (sel?.type === 'field') perform({ type: 'activateSet', zone: sel.idx });
      break;
    case 'attack':
      if (sel?.type === 'field') {
        sel.attackReady = true;
        sfx('select');
        renderDuel();
        toast('攻撃対象をタップ。相手モンスターがいなければ相手LPをタップ', 'gold');
      }
      break;
    case 'cancelAttack':
      if (sel) { sel.attackReady = false; renderDuel(); }
      break;
    case 'positionAtk':
      if (sel?.type === 'field') perform({ type: 'position', kind: sel.kind, idx: sel.idx, to: 'atk' });
      break;
    case 'positionDef':
      if (sel?.type === 'field') perform({ type: 'position', kind: sel.kind, idx: sel.idx, to: 'def' });
      break;
    case 'detail': {
      if (!sel) break;
      if (sel.type === 'extra') openCardDetail(sel.card, null, 'you');
      else if (sel.type === 'hand') openCardDetail(sel.card, null, 'you');
      else {
        const entry = d.entryAt('you', sel.kind, sel.idx);
        if (entry) openCardDetail(entry.card, entry, 'you');
      }
      break;
    }
    case 'extra':
      openExtraModal();
      break;
    case 'cancel':
      app.sel = null;
      renderDuel();
      break;
    case 'result':
      showResult();
      break;
    default:
      break;
  }
}

/* ---------------- engine actions ---------------- */
function runEngine(action, side) {
  const d = app.duel;
  switch (action.type) {
    case 'summon': return d.normalSummon(side, action.uid, action.zone, action.mode);
    case 'extra': return d.extraSummon(side, action.uid, action.slot);
    case 'activateSpell': return d.activateHandSpell(side, action.uid);
    case 'activateSet': return d.activateSetSpell(side, action.zone);
    case 'set': return d.setSpellTrap(side, action.uid, action.zone);
    case 'attack': return d.attack(side, action.kind, action.idx, action.target);
    case 'position': return d.changePosition(side, action.kind, action.idx, action.to);
    case 'end': return d.endTurn(side);
    default: throw new Error('未対応のアクションです');
  }
}

async function perform(action, { ai = false } = {}) {
  const d = app.duel;
  if (!d || d.winner) return false;
  const side = ai ? 'opp' : 'you';

  if (!ai) {
    if (app.busy || d.turn !== 'you') return false;
    app.busy = true;
  }

  const captured = captureRects();
  let events;
  try {
    events = runEngine(action, side);
  } catch (err) {
    if (!ai) {
      app.busy = false;
      toast(err.message || '実行できません', 'bad');
      sfx('click');
      renderDuel();
    }
    return false;
  }

  app.sel = null;
  renderDuel();
  await playEvents(events, captured, { duel: d });
  if (app.duel !== d) return false;

  if (!ai) {
    app.busy = false;
    renderDuel();
    if (d.winner) onDuelEnd();
    else if (d.turn === 'opp') { await sleep(160); runAiTurn(); }
  }
  return true;
}

/* ---------------- AI ---------------- */
async function runAiTurn() {
  const d = app.duel;
  if (!d || d.winner || aiRunning) return;
  const token = app.token;

  aiRunning = true;
  app.busy = true;
  app.sel = null;
  renderDuel();
  showTurnBannerSafe('opp');
  await sleep(800);

  let guard = 0;
  while (app.duel === d && app.token === token && !d.winner && d.turn === 'opp' && guard++ < 50) {
    const action = aiChoose(d, 'opp');
    if (!action || action.type === 'end') {
      await perform({ type: 'end' }, { ai: true });
      break;
    }
    const ok = await perform(action, { ai: true });
    if (!ok) {
      await perform({ type: 'end' }, { ai: true });
      break;
    }
    await sleep(340);
  }

  aiRunning = false;
  if (app.duel !== d || app.token !== token) return;

  app.busy = false;
  renderDuel();
  if (d.winner) onDuelEnd();
  else {
    showTurnBannerSafe('you');
    toast('あなたのターン', 'good');
  }
}

function showTurnBannerSafe(side) {
  // lazy import avoided: renderer is already registered on app
  if (app.showTurnBanner) app.showTurnBanner(side);
}

/* ---------------- extra / piles / card detail ---------------- */
function canExtraNow() {
  const d = app.duel;
  return !!d && d.turn === 'you' && !app.busy && !d.winner && !d.flags.extraSummoned
    && d.extra.you.length > 0 && d.ownMonsters('you').length >= 2 && d.emz.some(e => !e);
}

function openExtraModal() {
  const d = app.duel;
  if (!d || d.winner) return;
  const can = canExtraNow();
  const rows = d.extra.you.map((card, i) => `
    <button class="modal-list-card" data-ex="${i}" ${can ? '' : 'disabled'}>
      ${miniCardHTML(card)}
      <span class="mlc-text"><b>${esc(card.name)}</b><span>${typeLabel(card)} · ${esc(card.text)}</span></span>
      <span class="mlc-stat">ATK ${card.atk}</span>
    </button>
  `).join('');
  const body = openModal(`
    <div class="modal-title">EX召喚</div>
    <p class="modal-sub">モンスター2体を生贄に、中央のEXゾーンへ特殊召喚。1ターンに1回。</p>
    ${can ? '' : '<div class="detail-note">条件未達：自分のモンスター2体以上 / 空きEXゾーン / 1ターン1回 / 自分のターンであること。</div>'}
    <div class="modal-list">${rows || '<p class="tiny">EXデッキが空です。</p>'}</div>
    <div class="modal-actions"><button class="secondary-btn" data-close-modal>閉じる</button></div>
  `);
  body.querySelectorAll('[data-ex]').forEach(btn => {
    btn.addEventListener('click', () => {
      if (!can) return;
      const card = d.extra.you[Number(btn.dataset.ex)];
      if (!card) return;
      closeModal();
      app.sel = { type: 'extra', uid: card.uid, card };
      renderDuel();
      toast('空いているEXゾーンを選択（生贄2体）', 'gold');
    });
  });
}

function onPileClick(e) {
  const p = e.target.closest('[data-pile]');
  if (!p) return;
  openPile(p.dataset.side, p.dataset.pile);
}

function openPile(side, type) {
  const d = app.duel;
  if (!d) return;
  const labels = { deck: 'デッキ', gy: '墓地', extra: 'EXデッキ', banished: '除外' };
  const cards = type === 'deck' ? [] : type === 'extra' ? d.extra[side] : type === 'gy' ? d.gy[side] : d.banished[side];
  const title = `${side === 'you' ? '自分' : '相手'}の${labels[type] || type}`;

  if (type === 'deck') {
    openModal(`
      <div class="modal-title">${title}</div>
      <p class="modal-sub">山札の内容は非公開です。</p>
      <div class="detail-note">残り ${d.deck[side].length} 枚。ターン開始時に1枚ドローします。0枚でドローすると敗北。</div>
    `);
    return;
  }

  const rows = cards.slice().reverse().map((c, i) => `
    <button class="modal-list-card" data-index="${i}">
      ${miniCardHTML(c)}
      <span class="mlc-text"><b>${esc(c.name)}</b><span>${typeLabel(c)}</span></span>
      <span class="mlc-stat">${c.kind === 'monster' ? `ATK ${c.atk}<br>DEF ${c.def}` : c.rarity}</span>
    </button>
  `).join('');

  const body = openModal(`
    <div class="modal-title">${title}</div>
    <p class="modal-sub">${cards.length} 枚${type === 'extra' ? ' · 生贄2体でEXゾーンへ' : ''}</p>
    <div class="modal-list">${rows || '<p class="tiny">カードがありません。</p>'}</div>
  `);
  const rev = cards.slice().reverse();
  body.querySelectorAll('[data-index]').forEach(btn => {
    btn.addEventListener('click', () => {
      openCardDetail(rev[Number(btn.dataset.index)], null, side);
    });
  });
}

function openCardDetail(card, entry = null, side = 'you') {
  if (!card) return;
  const d = app.duel;

  if (entry?.faceDown && side !== 'you') {
    openModal(`
      <div class="modal-title">伏せられたカード</div>
      <p class="modal-sub">相手のセットカード</p>
      <div class="detail-note">内容は公開されていません。攻撃するか、効果で破壊すると公開されます。</div>
    `);
    return;
  }

  const atk = entry && d ? d.atkOf(side, entry) : card.atk;
  const def = entry && d ? d.defOf(side, entry) : card.def;
  const stats = card.kind === 'monster'
    ? `<div class="detail-stats">
         <div><span>ATK</span><b>${atk}</b></div>
         <div><span>DEF</span><b>${def}</b></div>
         <div><span>LEVEL</span><b>${card.level}</b></div>
       </div>`
    : `<div class="detail-stats">
         <div><span>TYPE</span><b style="font-size:12px">${esc(typeLabel(card))}</b></div>
         <div><span>RARITY</span><b style="font-size:12px">${card.rarity}</b></div>
       </div>`;

  const note = entry?.faceDown
    ? '<div class="detail-note">このカードはセットされています。攻撃すると公開されます。</div>'
    : card.extra
      ? '<div class="detail-note">EXモンスター：モンスター2体を生贄に、空いているEXゾーンへEX召喚します。</div>'
      : '';

  openModal(`
    <div class="card-detail">
      <div class="detail-card">${cardHTML(card, { entry, side, interactive: false })}</div>
      <div class="detail-info">
        <h3>${esc(card.name)}</h3>
        <div class="detail-meta">${esc(typeLabel(card))} · ${card.rarity}</div>
        <p>${esc(card.text)}</p>
        ${stats}
        ${note}
      </div>
    </div>
  `);
}

/* ---------------- log / leave / result ---------------- */
function openLogModal() {
  const d = app.duel;
  if (!d) return;
  const body = openModal(`
    <div class="modal-title">デュエルログ</div>
    <p class="modal-sub">T${d.turnNo} · ${d.logs.length} entries · ${esc(d.mode)}</p>
    <div class="log-full" id="logFull">
      ${d.logs.map(l => `<div class="log-full-row tone-${l.tone}"><span>T${l.turn}</span><p>${esc(l.text)}</p></div>`).join('')}
    </div>
  `);
  const full = body.querySelector('#logFull');
  if (full) full.scrollTop = full.scrollHeight;
}

function confirmLeave() {
  const d = app.duel;
  if (!d || d.winner) { exitDuel(); return; }
  const body = openModal(`
    <div class="modal-title">デュエルを退出しますか？</div>
    <p class="modal-sub">進行状況は保存されません。ルームには参加したままです。</p>
    <div class="modal-actions">
      <button class="primary-btn" id="leaveYes">退出する</button>
      <button class="secondary-btn" data-close-modal>続ける</button>
    </div>
  `);
  body.querySelector('#leaveYes').addEventListener('click', () => {
    closeModal(true);
    exitDuel();
  });
}

function exitDuel() {
  app.token += 1;
  app.duel = null;
  app.sel = null;
  app.busy = false;
  app.resultShown = false;
  aiRunning = false;
  closeModal(true);
  if (app.onExitDuel) app.onExitDuel();
  else showScreen('lobby');
}

function onDuelEnd() {
  if (!app.duel || app.resultShown) return;
  app.resultShown = true;
  addResult(app.duel.winner === 'you' ? 'win' : 'loss');
  setTimeout(() => {
    if (app.duel && app.duel.winner) showResult();
  }, 700);
}

function showResult() {
  const d = app.duel;
  if (!d) return;
  const win = d.winner === 'you';
  const body = openModal(`
    <div class="result-screen">
      <p class="result-eyebrow">DUEL ${win ? 'WON' : 'LOST'} · ${esc(d.mode)}</p>
      <h2 class="result-title ${win ? 'win' : 'lose'}">${win ? 'VICTORY' : 'DEFEAT'}</h2>
      <p class="modal-sub">${esc(d.overReason || '')}</p>
      <div class="result-lp">${d.lp.you} <span>LP</span> — ${d.lp.opp} <span>LP</span></div>
      <div class="result-stats">
        <div><span>TURNS</span><b>${d.turnNo}</b></div>
        <div><span>DECK LEFT</span><b>${d.deck.you.length}</b></div>
        <div><span>GRAVEYARD</span><b>${d.gy.you.length}</b></div>
      </div>
      <div class="modal-actions" style="justify-content:center">
        <button class="primary-btn" data-result="rematch">もう一度</button>
        <button class="secondary-btn" data-result="lobby">ロビーへ</button>
      </div>
    </div>
  `, { locked: true });
  body.querySelectorAll('[data-result]').forEach(btn => {
    btn.addEventListener('click', () => {
      const choice = btn.dataset.result;
      closeModal(true);
      if (choice === 'rematch' && app.lastConfig) startDuel(app.lastConfig);
      else exitDuel();
    });
  });
  sfx(win ? 'win' : 'lose');
}

