/* Boot: ambient FX, rooms, UI modules. */

import { initParticles } from './fx.js';
import { initRooms } from './rooms.js';
import { initCore } from './ui-core.js';
import { initLobby } from './ui-lobby.js';
import { initDuel } from './ui-duel.js';

initParticles();
initRooms();
initCore();
initLobby();
initDuel();

input.command:
cd /home/runner/work/PlayGround/PlayGround && for f in js/*.js; do node --check "$f" || echo "FAIL $f"; done && node --input-type=module -e "
import { DECKS, deckSize } from './js/cards.js';
for (const [id,d] of Object.entries(DECKS)) console.log(id, deckSize(d), d.extra.length);
"

cd /home/runner/work/PlayGround/PlayGround && node --input-type=module -e "
import { Duel } from './js/engine.js';
import { aiChoose } from './js/ai.js';

function apply(d, side, a) {
  switch (a.type) {
    case 'summon': return d.normalSummon(side, a.uid, a.zone, a.mode, []);
    case 'extra': return d.extraSummon(side, a.uid, a.slot, []);
    case 'activateSpell': return d.activateHandSpell(side, a.uid, -1, []);
    case 'activateSet': return d.activateSetSpell(side, a.zone, []);
    case 'set': return d.setSpellTrap(side, a.uid, a.zone, []);
    case 'attack': return d.attack(side, a.kind, a.idx, a.target, []);
    case 'end': return d.endTurn(side, []);
  }
  throw new Error('bad action ' + JSON.stringify(a));
}

let wins={you:0,opp:0}, errors=0, turns=[], stuck=0;
for (let g=0; g<300; g++) {
  const d = new Duel({playerName:'P', oppName:'C', deckId:['flame','abyss','gear'][g%3], oppDeckId:['abyss','gear','flame'][g%3]});
  let guard=0;
  while (!d.winner && guard++ < 600) {
    const side = d.turn;
    const a = aiChoose(d, side);
    try { apply(d, side, a); } catch(e) { errors++; console.log('ERR', e.message, a, 'turn',d.turn,'hand',d.hand[side].map(c=>c.name)); break; }
    if (a.type==='end' && d.turn===side) { stuck++; break; }
  }
  if (!d.winner) stuck++;
  else { wins[d.winner]++; turns.push(d.turnNo); }
}
console.log({wins, errors, stuck, avgTurns: turns.reduce((a,b)=>a+b,0)/turns.length, maxTurns: Math.max(...turns), minTurns: Math.min(...turns)});
"

