/* ---------------- duel shell ---------------- */
.duel-screen {
  height: 100dvh; min-height: 0;
  flex-direction: column; overflow: hidden;
  background:
    radial-gradient(100% 70% at 50% -10%, rgba(30, 70, 140, .22), transparent 60%),
    radial-gradient(80% 50% at 50% 110%, rgba(120, 40, 120, .12), transparent 65%),
    var(--bg);
}
.duel-screen.active { display: flex; }
.duel-top {
  position: relative; z-index: 5;
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 12px;
  padding: 10px 16px 8px;
  border-bottom: 1px solid rgba(120, 200, 255, .08);
  background: rgba(5, 7, 14, .6);
  backdrop-filter: blur(12px);
}
.duel-brand { font: 900 15px/1 var(--mono); letter-spacing: .06em; display: flex; align-items: baseline; gap: 2px; }
.duel-brand span { color: var(--cyan); }
.duel-brand small { font-size: 8px; letter-spacing: .18em; color: var(--dim); margin-left: 8px; }
.turn-pill {
  margin-left: auto;
  display: flex; align-items: center; gap: 8px;
  font: 700 10px/1 var(--mono); letter-spacing: .12em;
  padding: 8px 13px; border-radius: 100px;
  border: 1px solid rgba(77, 227, 255, .28);
  background: rgba(77, 227, 255, .07);
  color: var(--cyan);
  transition: .25s var(--ease);
}
.turn-pill i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; box-shadow: 0 0 10px currentColor; animation: blink 1.4s ease-in-out infinite; }
.turn-pill b { color: var(--dim); font-size: 9px; margin-left: 4px; }
.turn-pill.opp { color: var(--magenta); border-color: rgba(255, 77, 157, .3); background: rgba(255, 77, 157, .07); }
.turn-pill.over { color: var(--gold); border-color: rgba(255, 207, 107, .3); background: rgba(255, 207, 107, .08); }
.duel-room-label { font: 600 9px/1 var(--mono); letter-spacing: .1em; color: var(--dim); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.duel-top-actions { display: flex; gap: 6px; margin-left: auto; }
.duel-top-actions .icon-btn { width: 34px; height: 34px; }

.duel-main { flex: 1; min-height: 0; display: flex; justify-content: center; padding: 8px 14px 0; }
.board-frame { width: min(1200px, 100%); display: flex; flex-direction: column; min-height: 0; }
.board { flex: 1; min-height: 0; display: flex; flex-direction: column; justify-content: center; gap: 4px; position: relative; }

.side { flex: 0 0 auto; }
.strip {
  display: flex; align-items: center; gap: 14px;
  padding: 4px 6px;
}
.duelist { display: flex; align-items: center; gap: 9px; min-width: 150px; }
.duelist .avatar { width: 30px; height: 30px; border-radius: 9px; }
.duelist-text { min-width: 0; }
.duelist-text b { display: block; font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 130px; }
.duelist-text small { display: block; font: 600 8px/1 var(--mono); letter-spacing: .12em; color: var(--dim); margin-top: 4px; }
.lp-block { flex: 0 1 360px; min-width: 160px; cursor: default; border-radius: 8px; padding: 3px 4px; transition: .2s; }
.lp-block.targetable { cursor: crosshair; box-shadow: 0 0 0 1px var(--red), 0 0 24px -4px rgba(255, 92, 108, .8); animation: targetPulse 1s ease-in-out infinite; }
.lp-top { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.lp-top span { font: 700 8px/1 var(--mono); letter-spacing: .16em; color: var(--dim); }
.lp-value { font: 800 17px/1 var(--mono); letter-spacing: -.03em; color: #eaf5ff; transition: color .2s; }
.lp-value.hit { color: var(--red); }
.lp-bar { height: 5px; border-radius: 100px; background: rgba(255, 255, 255, .07); overflow: hidden; margin-top: 4px; }
.lp-bar i {
  display: block; height: 100%; width: 100%;
  border-radius: 100px;
  background: linear-gradient(90deg, #2d7dff, var(--cyan));
  box-shadow: 0 0 14px rgba(77, 227, 255, .5);
  transition: width .65s var(--ease), background .3s;
}
.side.opp .lp-bar i { background: linear-gradient(90deg, #ff4d9d, #ff8f5c); box-shadow: 0 0 14px rgba(255, 77, 157, .5); }
.lp-block.danger .lp-bar i { background: linear-gradient(90deg, #ff2d4d, #ff7a45); box-shadow: 0 0 16px rgba(255, 45, 77, .7); }
.lp-block.danger .lp-value { color: var(--red); }
.lp-block.heal .lp-value { color: var(--green); }

.piles { margin-left: auto; display: flex; gap: 5px; }
.pile {
  min-width: 46px; padding: 4px 6px;
  border: 1px solid var(--line); border-radius: 7px;
  background: rgba(255, 255, 255, .025);
  text-align: center; transition: .18s;
}
.pile:hover { border-color: var(--line-strong); background: rgba(77, 227, 255, .06); }
.pile span { display: block; font: 700 7px/1 var(--mono); letter-spacing: .1em; color: var(--dim); }
.pile b { display: block; font: 800 12px/1 var(--mono); margin-top: 3px; color: #dbe8ff; }
.pile.deck b { color: var(--cyan); }
.pile.gy b { color: var(--violet); }
.pile.banished b { color: var(--gold); }
.pile.extra b { color: var(--magenta); }

.side-field {
  display: grid; grid-template-columns: calc(var(--zone-h) * .74) minmax(0, 1fr);
  gap: 8px; align-items: center;
  padding: 2px 6px;
}
.field-rail { display: flex; align-items: center; justify-content: center; }
.rows { display: flex; flex-direction: column; gap: 5px; width: 100%; max-width: 780px; margin: 0 auto; }
.zone-row { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 5px; justify-items: center; }
.side.you .rows { flex-direction: column; }
.row-tag {
  position: absolute; left: -40px; top: 50%; transform: translateY(-50%) rotate(-90deg);
  font: 700 7px/1 var(--mono); letter-spacing: .2em; color: var(--dim);
}
.side-field .rows { position: relative; }

/* ---------------- zones ---------------- */
.zone {
.log-strip .log-item span { max-width: 46vw; overflow: hidden; text-overflow: ellipsis; }
.log-strip .log-turn { margin-left: auto; color: var(--dim); font-size: 8px; letter-spacing: .12em; }

/* ---------------- footer / hand ---------------- */
.duel-bottom {
  position: relative; z-index: 4;
  flex: 0 0 auto;
  padding: 6px 14px max(8px, env(safe-area-inset-bottom));
  background: linear-gradient(180deg, rgba(5, 7, 14, 0), rgba(5, 7, 14, .85) 24%);
}
.action-tray {
  min-height: 46px;
  display: flex; align-items: center; gap: 8px;
  padding: 5px 8px;
  border: 1px solid rgba(120, 200, 255, .1);
  border-radius: 11px;
  background: rgba(12, 17, 32, .72);
  backdrop-filter: blur(10px);
  margin-bottom: 6px;
  overflow-x: auto;
  scrollbar-width: none;
}
.action-tray::-webkit-scrollbar { display: none; }
.tray-hint {
  display: flex; align-items: center; gap: 7px;
  color: var(--muted); font-size: 10.5px; padding: 0 4px;
  white-space: nowrap;
}
.tray-hint i { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); animation: blink 1.6s infinite; }
.tray-card-name {
  display: flex; align-items: center; gap: 7px;
  padding: 5px 9px; border-radius: 7px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .04);
  font-size: 10.5px; font-weight: 700; white-space: nowrap;
  max-width: 260px;
}
.tray-card-name .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent, var(--cyan)); box-shadow: 0 0 8px var(--accent, var(--cyan)); }
.tray-card-name span { overflow: hidden; text-overflow: ellipsis; }
.tray-btn {
  flex: 0 0 auto;
  padding: 8px 12px; border-radius: 8px;
  border: 1px solid var(--line-strong);
  background: rgba(255, 255, 255, .045);
  font-size: 10.5px; font-weight: 800; letter-spacing: .02em;
  transition: .16s var(--ease);
  white-space: nowrap;
}
.tray-btn:hover:not(:disabled) { background: rgba(77, 227, 255, .12); border-color: var(--cyan); transform: translateY(-1px); }
.tray-btn.primary { background: linear-gradient(135deg, #7df1ff, #4de3ff 50%, #4d7dff); color: #031019; border-color: transparent; }
.tray-btn.primary:hover:not(:disabled) { filter: brightness(1.08); }
.tray-btn.danger { color: #ffb3bc; border-color: rgba(255, 92, 108, .45); background: rgba(255, 92, 108, .08); }
.tray-btn.gold { color: #171006; background: var(--gold); border-color: transparent; }
.tray-spacer { flex: 1; }
.tray-turn { font: 700 9px/1 var(--mono); letter-spacing: .1em; color: var(--dim); }

.hand-zone { min-width: 0; }
.hand-meta { display: flex; align-items: center; gap: 10px; padding: 0 4px 5px; font: 700 9px/1 var(--mono); letter-spacing: .1em; color: var(--dim); }
.hand-meta b { color: var(--text); }
.ex-btn {
  font: 700 9px/1 var(--mono); letter-spacing: .06em;
  padding: 5px 8px; border-radius: 6px;
  border: 1px solid rgba(255, 77, 157, .3);
  background: rgba(255, 77, 157, .08);
  color: #ffb9d5;
  transition: .18s;
}
.ex-btn:hover { background: rgba(255, 77, 157, .16); }
.hand-tip { margin-left: auto; color: var(--dim); font-weight: 600; letter-spacing: .02em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.hand {
  display: flex; justify-content: center; align-items: flex-end;
  gap: 6px; min-height: calc(var(--hand-h) + 8px);
  padding: 2px 6px 0;
}
.hand-card {
  position: relative;
  flex: 0 0 auto;
  width: calc(var(--hand-h) * .715);
  height: var(--hand-h);
  padding: 0; border: 0; background: none;
  border-radius: 8px;
  transition: transform .18s var(--ease), filter .18s;
  transform-origin: bottom center;
}
.hand-card:hover { transform: translateY(-8px) scale(1.03); z-index: 5; }
.hand-card.selected { transform: translateY(-13px) scale(1.045); z-index: 6; filter: drop-shadow(0 0 14px rgba(255, 207, 107, .55)); }
.hand-card.selected .card-inner { border-color: var(--gold); box-shadow: inset 0 0 0 1px rgba(0,0,0,.5), 0 0 0 1px var(--gold), 0 10px 28px rgba(0,0,0,.6); }
.hand-card .card-name { font-size: 9px; }
.hand-card .card-stars { font-size: 6px; }
.hand-card .card-glyph { font-size: calc(var(--hand-h) * .22); }
.hand-card .card-type { font-size: 6.5px; }
.hand-card .card-text {
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical;
  overflow: hidden; font-size: 6px; line-height: 1.35; color: #9fb1d0;
  margin-top: 2px; flex: 0 0 auto;
}
.hand-card .card-foot b { font-size: 8px; }
.hand-card .card-foot { font-size: 6px; }
.hand-empty {
  height: var(--hand-h); display: flex; align-items: center; justify-content: center;
  color: var(--dim); font: 600 10px/1.5 var(--mono); letter-spacing: .1em; text-align: center;
}

/* ---------------- modal / toast / banner ---------------- */
.modal-root {
  position: fixed; inset: 0; z-index: 100;
  display: grid; place-items: center;
  padding: 18px;
}
.modal-root[hidden] { display: none; }
.modal-backdrop { position: absolute; inset: 0; background: rgba(2, 4, 10, .72); backdrop-filter: blur(7px); animation: fadeIn .2s ease; }
.modal-card {
  position: relative; z-index: 1;
  width: min(560px, 100%); max-height: min(86dvh, 780px);
  display: flex; flex-direction: column;
  border-radius: 18px;
    grid-template-areas:
      "hero side"
      "rooms rooms";
  }
  .room-table-head, .room-row { grid-template-columns: minmax(170px, 1.6fr) .7fr .5fr .5fr .8fr 88px; }
  .room-table-head span:nth-child(4), .room-row > :nth-child(4) { display: none; }
  .room-hero { grid-template-columns: 1fr; }
  .room-hero-side { align-items: flex-start; }
}

