  .room-join { grid-area: join; align-self: center; }
  .room-row > :nth-child(7) { grid-area: join; }
  .room-meta-mobile { grid-area: meta; display: flex; gap: 8px; flex-wrap: wrap; }
  .duel-top { padding: 6px 10px; gap: 8px; }
  .duel-brand small { display: none; }
  .turn-pill { padding: 6px 10px; font-size: 9px; }
  .duel-main { padding: 4px 6px 0; }
  .strip { gap: 8px; padding: 2px 3px; }
  .duelist { min-width: 0; flex: 1; }
  .duelist .avatar { width: 24px; height: 24px; font-size: 10px; }
  .duelist-text b { font-size: 9.5px; max-width: 88px; }
  .duelist-text small { font-size: 6.5px; }
  .lp-block { flex: 0 1 46%; min-width: 0; padding: 2px; }
  .lp-top span { font-size: 6.5px; }
  .lp-value { font-size: 13px; }
  .lp-bar { height: 4px; }
  .piles { gap: 3px; }
  .pile { min-width: 0; padding: 3px 4px; border-radius: 5px; }
  .pile span { font-size: 5.5px; }
  .pile b { font-size: 9px; margin-top: 2px; }
  .pile.banished { display: none; }
  .side-field { grid-template-columns: calc(var(--zone-h) * .58) minmax(0, 1fr); gap: 5px; padding: 0 2px; }
  .rows { gap: 4px; }
  .zone-row { gap: 4px; }
  .zone { border-radius: 5px; }
  .zone-empty-label { font-size: 5.5px; }
  .zone-empty-label b { font-size: 8px; }
  .card-name { font-size: 7px; }
  .card-stars { font-size: 4.5px; }
  .card-type { font-size: 5px; }
  .card-foot { font-size: 4.5px; }
  .card-foot b { font-size: 6px; }
  .card-rank { font-size: 4px; }
  .set-badge, .pos-badge { font-size: 4px; padding: 2px 3px; }
  .center-strip { padding: 1px 3px; }
  .center-badge { padding: 0 4px; }
  .center-badge b { font-size: 12px; }
  .center-badge span { font-size: 5px; }
  .emz-caption { font-size: 5px; }
  .log-strip { height: 22px; font-size: 8px; gap: 8px; padding: 0 4px; }
  .log-strip .log-turn { display: none; }
  .duel-bottom { padding: 4px 6px max(6px, env(safe-area-inset-bottom)); }
  .action-tray { min-height: 40px; padding: 4px 6px; gap: 6px; border-radius: 9px; }
  .tray-hint { font-size: 9px; }
  .tray-card-name { font-size: 9px; max-width: 140px; padding: 4px 7px; }
  .tray-btn { font-size: 9px; padding: 7px 9px; border-radius: 7px; }
  .hand-meta { font-size: 8px; padding-bottom: 3px; gap: 7px; }
  .hand { gap: 3px; padding: 0 2px; min-height: calc(var(--hand-h) + 4px); }
  .hand-card { width: calc(var(--hand-h) * .7); }
  .hand-card .card-name { font-size: 8px; }
  .hand-card .card-text { -webkit-line-clamp: 2; font-size: 5.5px; }
  .hand-tip { display: none; }
  .hand-empty { font-size: 8px; }
  .modal-body { padding: 20px 16px 16px; }
  .card-detail { grid-template-columns: 1fr; justify-items: center; }
  .card-detail .detail-card { width: 148px; height: 208px; }
  .detail-info { width: 100%; }
  .result-title { font-size: 34px; }
  .room-rules { grid-template-columns: 1fr; }
  .room-hero { padding: 20px; }
  .room-hero::after { display: none; }
  .toasts { bottom: max(12px, env(safe-area-inset-bottom)); }
}

@media (max-width: 430px) {
  .brand-text small { display: none; }
  .brand-mark { width: 38px; height: 38px; font-size: 15px; }
  .brand-text b { font-size: 14px; }
  .online-pill span { display: none; }
  .profile-name { max-width: 96px; }
  .topbar { gap: 8px; }
