      const side=d.turn;
      const action=aiChoose(d,side);
      let ev;
      switch(action.type){
        case 'summon': ev=d.normalSummon(side,action.uid,action.zone,action.mode); break;
        case 'extra': ev=d.extraSummon(side,action.uid,action.slot); break;
        case 'activateSpell': ev=d.activateHandSpell(side,action.uid); break;
