        case 'set': ev=d.setSpellTrap(side,action.uid,action.zone); break;
        case 'attack': ev=d.attack(side,action.kind,action.idx,action.target); break;
        case 'end': ev=d.endTurn(side); break;
        default: throw new Error('unknown '+action.type);
